mapper.select:
SELECT activity.*, v.shop_id, s.name AS shop_name, v.title, v.pay_value, v.actual_value FROM ( SELECT o.id AS order_id, o.voucher_id, o.status AS order_status, NULL AS message_status, o.create_time, o.pay_time FROM tb_voucher_order o WHERE o.user_id = #{userId}
AND o.status = 2
UNION ALL SELECT m.order_id, m.voucher_id, NULL, m.status, m.create_time, NULL FROM tb_mq_message m WHERE m.user_id = #{userId} AND m.topic = #{topic} AND NOT EXISTS (SELECT 1 FROM tb_voucher_order o WHERE o.id = m.order_id)
UNION ALL SELECT #{r.orderId}, #{r.voucherId}, NULL, #{r.messageStatus}, #{r.createTime}, NULL WHERE NOT EXISTS (SELECT 1 FROM tb_voucher_order o WHERE o.id = #{r.orderId}) AND NOT EXISTS (SELECT 1 FROM tb_mq_message m WHERE m.order_id = #{r.orderId} AND m.topic = #{topic})
) activity LEFT JOIN tb_voucher v ON v.id = activity.voucher_id LEFT JOIN tb_shop s ON s.id = v.shop_id ORDER BY activity.create_time DESC, activity.order_id DESC
